package com.parvnigam.careerbridge;

import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import javax.imageio.ImageIO;
import org.apache.pdfbox.pdmodel.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.security.oauth2.jwt.JwtEncoder;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:academicreviews;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop","app.upload-dir=target/academic-review-test-uploads","app.mail-enabled=false","app.local-email-testing=false","app.ai-url=","app.redis-enabled=false"})
class AcademicReviewTests {
    @LocalServerPort int port;
    @Autowired Store r;@Autowired JwtEncoder encoder;
    final HttpClient http=HttpClient.newHttpClient();final JsonMapper json=JsonMapper.builder().build();
    HttpResponse<String> call(String method,String path,String jwt,Object body)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api"+path));if(jwt!=null)b.header("Authorization","Bearer "+jwt);if(body!=null)b.header("Content-Type","application/json");return http.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
    JsonNode tree(HttpResponse<String> response){return json.readTree(response.body());}
    String token(Model.Account a){return SecurityConfig.token(encoder,a);}
    Model.Account seeded(String email){return r.accounts().findByEmail(email).orElseThrow();}
    String staff(){return token(seeded("placement@careerbridge.dev"));}String admin(){return token(seeded("admin@careerbridge.dev"));}String recruiter(){return token(seeded("recruiter@careerbridge.dev"));}
    Model.Account account(Model.Role role,Long university){var a=new Model.Account();a.name="Academic Review "+UUID.randomUUID();a.email=UUID.randomUUID()+"@example.com";a.role=role;a.universityId=university;a.emailVerified=true;a.passwordHash=seeded("student@careerbridge.dev").passwordHash;r.accounts().save(a);if(role==Model.Role.STUDENT){var p=new Model.Profile();p.userId=a.id;p.skills=new ArrayList<>(List.of("Java"));r.profiles().save(p);}return a;}
    Map<String,Object> academicInput(){var m=new LinkedHashMap<String,Object>();m.putAll(Map.of("tenthInstitution","Review School","tenthBoard","ICSE","tenthYear",2022,"tenthScoreType","PERCENTAGE","tenthScore",96.0));m.putAll(Map.of("secondaryQualification","TWELFTH","secondaryInstitution","Review School","secondaryBoard","ISC","secondaryYear",2024,"secondaryScoreType","PERCENTAGE","secondaryScore",94.0));m.putAll(Map.of("collegeInstitution","Review College","degree","B.Tech","department","Computer Science","graduationYear",2028,"currentSemester",5,"cgpa",9.0,"activeBacklogs",0,"clearedBacklogs",0,"gapYears",0));return m;}
    Model.Account student()throws Exception{var a=account(Model.Role.STUDENT,seeded("placement@careerbridge.dev").universityId);var result=call("PUT","/student/academics",token(a),academicInput());assertEquals(200,result.statusCode(),result.body());return r.accounts().findById(a.id).orElseThrow();}
    byte[] pdf()throws Exception{try(var pdf=new PDDocument();var out=new ByteArrayOutputStream()){pdf.addPage(new PDPage());pdf.save(out);return out.toByteArray();}}
    byte[] image(String type)throws Exception{var b=new java.awt.image.BufferedImage(8,8,java.awt.image.BufferedImage.TYPE_INT_RGB);try(var out=new ByteArrayOutputStream()){ImageIO.write(b,type,out);return out.toByteArray();}}
    HttpResponse<String> upload(String jwt,String kind,String name,byte[] bytes)throws Exception{String boundary="review-"+UUID.randomUUID();var out=new ByteArrayOutputStream();out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"kind\"\r\n\r\n"+kind+"\r\n--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+name+"\"\r\nContent-Type: text/html\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(bytes);out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/student/academic-documents")).header("Content-Type","multipart/form-data; boundary="+boundary);if(jwt!=null)b.header("Authorization","Bearer "+jwt);return http.send(b.POST(HttpRequest.BodyPublishers.ofByteArray(out.toByteArray())).build(),HttpResponse.BodyHandlers.ofString());}
    List<Long> documents(Model.Account a)throws Exception{var ids=new ArrayList<Long>();for(String kind:List.of("TENTH","SECONDARY","COLLEGE")){var response=upload(token(a),kind,kind+"-proof.pdf",pdf());assertEquals(201,response.statusCode(),response.body());assertFalse(tree(response).has("storageKey"));assertEquals("application/pdf",tree(response).get("mediaType").asText());ids.add(tree(response).get("id").asLong());}return ids;}
    long revision(Model.Account a){return AcademicReviewService.revision(r.profiles().findByUserId(a.id).orElseThrow());}
    HttpResponse<String> submit(Model.Account a,List<Long> ids)throws Exception{return call("POST","/student/academic-submissions",token(a),Map.of("documentIds",ids,"academicRevision",revision(a),"note","Please check my latest academic results."));}
    JsonNode pending(Model.Account a,List<Long> ids)throws Exception{var result=submit(a,ids);assertEquals(201,result.statusCode(),result.body());return tree(result);}
    HttpResponse<String> review(JsonNode submission,String jwt,String status,String note)throws Exception{return call("PATCH","/placement/academic-reviews/"+submission.get("id").asLong(),jwt,Map.of("version",submission.get("version").asLong(),"status",status,"note",note,"documentsChecked",true));}
    String status(Model.Account a)throws Exception{return tree(call("GET","/student/profile",token(a),null)).get("academicVerification").get("status").asText();}

    @Test void approvalPersistsAndRecruitersSeeStatusWithoutPrivateDocuments()throws Exception{var a=student();var ids=documents(a);var submission=pending(a,ids);assertEquals("PENDING",status(a));assertEquals(200,review(submission,staff(),"VERIFIED","Documents match the submitted record.").statusCode());assertEquals("VERIFIED",status(a));assertEquals(Model.AcademicReviewStatus.VERIFIED,r.academicSubmissions().findById(submission.get("id").asLong()).orElseThrow().status);String candidates=call("GET","/recruiter/candidates",recruiter(),null).body();assertTrue(candidates.contains("VERIFIED"));assertFalse(candidates.contains("TENTH-proof.pdf"));assertFalse(candidates.contains("Documents match"));assertFalse(candidates.contains("storageKey"));var j=new Model.Job();j.recruiterId=seeded("recruiter@careerbridge.dev").id;j.title="Review evidence test opening";j.companyName="Demo Company";j.description="Java internship";j.location="Delhi";j.requiredSkills=new ArrayList<>(List.of("Java"));r.jobs().save(j);assertEquals(201,call("POST","/student/applications",token(a),Map.of("jobId",j.id)).statusCode());String pipeline=call("GET","/recruiter/applications",recruiter(),null).body();assertTrue(pipeline.contains("VERIFIED"));assertFalse(pipeline.contains("TENTH-proof.pdf"));assertTrue(call("GET","/placement/export",staff(),null).body().contains("Academic Review Status"));assertTrue(call("GET","/notifications",token(a),null).body().contains("Academic record verified"));assertTrue(call("GET","/admin/audit",admin(),null).body().contains("ACADEMICS_REVIEWED"));assertEquals(409,review(submission,staff(),"VERIFIED","").statusCode());assertEquals(409,submit(a,ids).statusCode());}
    @Test void documentsAndReviewAreRestrictedToOwnerAndCampusStaff()throws Exception{var a=student();var other=student();var ids=documents(a);var submission=pending(a,ids);String path="/academic-documents/"+ids.get(0)+"/download";assertEquals(401,call("GET",path,null,null).statusCode());assertEquals(403,call("GET",path,token(other),null).statusCode());assertEquals(403,call("GET",path,recruiter(),null).statusCode());var outsider=account(Model.Role.PLACEMENT_OFFICER,a.universityId+999);assertEquals(403,call("GET",path,token(outsider),null).statusCode());assertEquals(403,review(submission,token(outsider),"VERIFIED","").statusCode());assertEquals(403,review(submission,token(a),"VERIFIED","").statusCode());assertEquals(403,call("GET","/placement/academic-reviews",recruiter(),null).statusCode());assertFalse(call("GET","/placement/academic-reviews?status=ALL",token(outsider),null).body().contains(a.email));for(String jwt:List.of(token(a),staff(),admin())){var response=call("GET",path,jwt,null);assertEquals(200,response.statusCode(),response.body());assertTrue(response.headers().firstValue("Content-Type").orElseThrow().startsWith("application/pdf"));assertEquals("nosniff",response.headers().firstValue("X-Content-Type-Options").orElseThrow());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());assertTrue(response.headers().firstValue("Content-Disposition").orElseThrow().startsWith("attachment"));}assertEquals(403,submit(other,ids).statusCode());assertEquals(403,call("DELETE","/student/academic-documents/"+ids.get(0),token(other),null).statusCode());}
    @Test void academicEditsInvalidateApprovalAndSnapshotsStayImmutable()throws Exception{var a=student();var ids=documents(a);var s=pending(a,ids);assertEquals(200,review(s,staff(),"VERIFIED","").statusCode());var changed=academicInput();changed.put("tenthScore",88.0);assertEquals(200,call("PUT","/student/academics",token(a),changed).statusCode());assertEquals("NEEDS_RESUBMISSION",status(a));var workspace=tree(call("GET","/student/academic-documents",token(a),null));assertEquals(96.0,workspace.get("submissions").get(0).get("snapshot").get("profile").get("academics").get("tenthScore").asDouble());assertEquals(200,call("PUT","/student/academics",token(a),academicInput()).statusCode());assertEquals("NEEDS_RESUBMISSION",status(a));assertEquals(409,review(s,staff(),"VERIFIED","").statusCode());var next=pending(a,ids);assertEquals(200,review(next,staff(),"VERIFIED","").statusCode());assertEquals("VERIFIED",status(a));assertEquals(2,tree(call("GET","/student/academic-documents",token(a),null)).get("submissions").size());}
    @Test void pendingEditsAndStaleSubmissionVersionsCannotBeApproved()throws Exception{var a=student();var ids=documents(a);long before=revision(a);var s=pending(a,ids);var changed=academicInput();changed.put("activeBacklogs",1);assertEquals(200,call("PUT","/student/academics",token(a),changed).statusCode());assertEquals("NEEDS_RESUBMISSION",status(a));assertEquals(409,review(s,staff(),"VERIFIED","").statusCode());assertEquals(409,call("POST","/student/academic-submissions",token(a),Map.of("documentIds",ids,"academicRevision",before)).statusCode());var next=pending(a,ids);assertEquals(409,call("PATCH","/placement/academic-reviews/"+next.get("id").asLong(),staff(),Map.of("version",999,"status","VERIFIED","documentsChecked",true)).statusCode());assertEquals(400,call("PATCH","/placement/academic-reviews/"+next.get("id").asLong(),staff(),Map.of("version",next.get("version").asLong(),"status","VERIFIED","documentsChecked",false)).statusCode());assertEquals(200,review(next,admin(),"VERIFIED","").statusCode());}
    @Test void correctionsNeedAReasonAndCanBeResubmittedWithReplacementEvidence()throws Exception{var a=student();var ids=documents(a);var s=pending(a,ids);assertEquals(400,review(s,staff(),"CHANGES_REQUESTED","  ").statusCode());assertEquals(200,review(s,staff(),"CHANGES_REQUESTED","The college transcript is unclear. Upload a readable copy.").statusCode());assertEquals("CHANGES_REQUESTED",status(a));var extra=upload(token(a),"COLLEGE","clear-transcript.png",image("png"));assertEquals(201,extra.statusCode(),extra.body());var newIds=new ArrayList<>(ids);newIds.set(2,tree(extra).get("id").asLong());var replacement=pending(a,newIds);assertEquals(409,submit(a,newIds).statusCode());assertEquals(200,review(replacement,staff(),"VERIFIED","").statusCode());assertTrue(call("GET","/student/academic-documents",token(a),null).body().contains("Upload a readable copy"));assertEquals(409,call("DELETE","/student/academic-documents/"+ids.get(2),token(a),null).statusCode());assertEquals(200,call("GET","/academic-documents/"+ids.get(2)+"/download",staff(),null).statusCode());}
    @Test void uploadsValidateContentsAndUnusedFilesCanBeDeleted()throws Exception{var a=student();String jwt=token(a);assertEquals(400,upload(jwt,"TENTH","fake.pdf","<script>bad</script>".getBytes()).statusCode());assertEquals(400,upload(jwt,"TENTH","fake.jpg",image("png")).statusCode());assertEquals(400,upload(jwt,"TENTH","unsupported.html",pdf()).statusCode());assertEquals(400,upload(jwt,"TENTH","empty.pdf",new byte[0]).statusCode());assertEquals(413,upload(jwt,"TENTH","large.pdf",new byte[5*1024*1024+1]).statusCode());assertEquals(0,tree(call("GET","/student/academic-documents",jwt,null)).get("documents").size());var jpeg=upload(jwt,"OTHER","backlog.jpg",image("jpeg"));assertEquals(201,jpeg.statusCode(),jpeg.body());long id=tree(jpeg).get("id").asLong();assertEquals(200,call("DELETE","/student/academic-documents/"+id,jwt,null).statusCode());assertEquals(404,call("GET","/academic-documents/"+id+"/download",jwt,null).statusCode());assertFalse(r.academicDocuments().existsById(id));}
    @Test void incompleteAcademicsAndMissingOrDuplicateCategoriesCannotBeSubmitted()throws Exception{var a=account(Model.Role.STUDENT,seeded("placement@careerbridge.dev").universityId);var ids=documents(a);assertEquals("NOT_SUBMITTED",status(a));assertEquals(400,submit(a,ids).statusCode());assertEquals(200,call("PUT","/student/academics",token(a),academicInput()).statusCode());assertEquals(400,submit(a,List.of(ids.get(0),ids.get(0),ids.get(2))).statusCode());assertEquals(400,submit(a,List.of(ids.get(0),ids.get(1))).statusCode());assertEquals(400,submit(a,List.of(ids.get(0),ids.get(1),999999L)).statusCode());var fourth=upload(token(a),"TENTH","extra-tenth.pdf",pdf());assertEquals(201,fourth.statusCode());assertEquals(400,submit(a,List.of(ids.get(0),ids.get(1),tree(fourth).get("id").asLong())).statusCode());assertEquals(201,submit(a,ids).statusCode());}
    @Test void concurrentSubmissionsAndDecisionsHaveExactlyOneWinner()throws Exception{var a=student();var ids=documents(a);var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);Callable<Integer> submit=()->{start.await();return submit(a,ids).statusCode();};var one=pool.submit(submit);var two=pool.submit(submit);start.countDown();var codes=new ArrayList<>(List.of(one.get(),two.get()));Collections.sort(codes);assertEquals(List.of(201,409),codes);var s=tree(call("GET","/student/academic-documents",token(a),null)).get("submissions").get(0);var reviewStart=new CountDownLatch(1);Callable<Integer> decide=()->{reviewStart.await();return review(s,staff(),"VERIFIED","").statusCode();};one=pool.submit(decide);two=pool.submit(decide);reviewStart.countDown();codes=new ArrayList<>(List.of(one.get(),two.get()));Collections.sort(codes);assertEquals(List.of(200,409),codes);assertEquals("VERIFIED",status(a));}finally{pool.shutdownNow();}}
    @Test void UnrelatedProfileEditsAndNoOpAcademicSavesPreserveApprovalButCgpaChangesDoNot()throws Exception{var a=student();var s=pending(a,documents(a));assertEquals(200,review(s,staff(),"VERIFIED","").statusCode());long rev=revision(a);assertEquals(200,call("PUT","/student/academics",token(a),academicInput()).statusCode());assertEquals(rev,revision(a));assertEquals("VERIFIED",status(a));assertEquals(200,call("PUT","/student/profile",token(a),Map.of("headline","Updated headline","cgpa",9.0,"skills",List.of("Java","React"),"visibleToRecruiters",false)).statusCode());assertEquals("VERIFIED",status(a));assertFalse(call("GET","/recruiter/candidates",recruiter(),null).body().contains(a.name));assertTrue(call("GET","/placement/analytics",staff(),null).body().contains(a.name));assertEquals(200,call("PUT","/student/profile",token(a),Map.of("cgpa",9.1,"visibleToRecruiters",true)).statusCode());assertEquals("NEEDS_RESUBMISSION",status(a));}
    @Test void branchGraduationAndBacklogChangesAlsoNeedANewReview()throws Exception{var a=student();var ids=documents(a);for(var change:List.<Map<String,Object>>of(Map.of("department","Information Technology"),Map.of("graduationYear",2029),Map.of("activeBacklogs",1))){assertEquals(200,call("PUT","/student/academics",token(a),academicInput()).statusCode());var s=pending(a,ids);assertEquals(200,review(s,staff(),"VERIFIED","").statusCode());var changed=academicInput();changed.putAll(change);var result=call("PUT","/student/academics",token(a),changed);assertEquals(200,result.statusCode(),result.body());assertEquals("NEEDS_RESUBMISSION",status(a));}}

}
